<?php require_once __DIR__.'/../../includes/bootstrap.php';require_role('Administrator','IT');$pageTitle='Email Logs';$rows=db()->query('SELECT * FROM email_logs ORDER BY created_at DESC LIMIT 100')->fetchAll();require __DIR__.'/../../includes/header.php';?><div class="admin-shell"><aside class="sidebar"><?php require __DIR__.'/../sidebar.php';?></aside><section class="admin-content"><div class="admin-top"><div><div class="eyebrow">Communications</div><h1 class="admin-title">Email delivery logs</h1><p class="kicker">Production transport can use SMTP or an email API; local development records delivery state here.</p></div></div><div class="panel table-wrap"><table class="table"><thead><tr><th>Recipient</th><th>Subject</th><th>Status</th><th>Created</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['recipient_email'])?></td><td><?=e($r['subject'])?></td><td><span class="badge <?=$r['status']==='sent'?'badge-green':($r['status']==='failed'?'badge-red':'badge-gold')?>"><?=e($r['status'])?></span></td><td><?=date('d M Y · H:i',strtotime($r['created_at']))?></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="4">No email records yet.</td></tr><?php endif;?></tbody></table></div></section></div><?php require __DIR__.'/../../includes/footer.php';?>
